// spec: specs/events.md
// seed: tests/seed.client.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/client.json') });

const EVENT_URL = '/events/087e8dd0-3043-4e55-b182-c2b646c7b7f8';

test.describe('רכישת כרטיס לאירוע', () => {
  test('כמות כרטיסים 1–6 וסה"כ = מחיר × כמות @android @prod-safe #6a86f7bc4808', async ({ page }) => {
    // 1. לפתוח את האירוע
    await page.goto(EVENT_URL);
    const plus = page.getByRole('button', { name: 'הוספת כרטיס' });
    const minus = page.getByRole('button', { name: 'הפחתת כרטיס' });
    const qty = page.getByTestId('qty-value');
    const total = page.getByTestId('summary-total');
    await expect(plus).toBeVisible();

    // 2. מונה ו"הפחתת כרטיס"
    await expect(qty).toHaveText('1');
    await expect(minus).toBeDisabled();

    // 3. רדיו "QA VIP, ₪1,850"
    await page.getByRole('radio', { name: 'QA VIP, ₪1,850' }).click();
    await expect(page.getByRole('radio', { name: 'QA VIP, ₪1,850' })).toBeChecked();
    await expect(page.getByRole('radio', { name: 'QA רגיל, ₪5.50' })).not.toBeChecked();
    await expect(page.getByTestId('summary-type-name')).toHaveText('QA VIP');
    await expect(page.getByTestId('summary-qty')).toHaveText('1');
    await expect(total).toHaveText('₪1,850');

    // 4. "הוספת כרטיס" × 1, ואז × 4
    await plus.click();
    await expect(qty).toHaveText('2');
    await expect(total).toHaveText('₪3,700');

    for (let i = 0; i < 4; i++) await plus.click();
    await expect(qty).toHaveText('6');
    await expect(total).toHaveText('₪11,100');
    await expect(plus).toBeDisabled();
    await expect(page.getByText('עד 6 כרטיסים ברכישה', { exact: true })).toBeVisible();

    // 5. "הפחתת כרטיס" × 5
    for (let i = 0; i < 5; i++) await minus.click();
    await expect(qty).toHaveText('1');
    await expect(total).toHaveText('₪1,850');
    await expect(minus).toBeDisabled();
    await expect(plus).toBeEnabled();
    // "קניית כרטיס" לא נלחץ
  });
});
